fn is_prime(n: i8) -> bool {
    // If n is less than 2, it's not prime by definition.
    if n < 2 {
        return false;
    }

    // We'll check all divisors k from 2 (inclusive) up to n (exclusive).
    // Invariants:
    //  - n >= 2
    //  - divisor k ∈ [2, n]
    //  - for all j in [2, k), n % j != 0
    //
    // Termination measure: n - k, which decreases strictly each iteration.
    //
    // If we find any k dividing n, return false immediately.
    //
    // If none divide n, return true: n is prime.

    let mut divisor: i8 = 2;

    while divisor < n {
        if n % divisor == 0 {
            // Found a divisor → not prime.
            return false;
        }

        divisor += 1; // increase divisor and continue loop
    }
    
    // No divisor found in [2, n-1] → n is prime
    true
}